models.rawContent:
{  
  "discoveries": [  
    "日本語の注意サイン（カーブミラー）を正しく見つけ、正解国を特定できました。",  
    "黄緑色のガードレール（bollard）を観察できていますが、色だけでは国を絞り込む材料が不足しています。"  
  ],  
  "discriminationHint": "次回は、以下のスロットを意識的に確認すると、言語情報が無くても判定がしやすくなります。",  
  "failureModeExplanation": "正解タグや用語辞書が提供されていないため、見落としや過剰申告についての判定は行えません。したがって、ここでは「見落としの判定はできません」と明示します。",  
  "judgmentUnavailable": true,  
  "missedClues": [],  
  "nextPriority": [  
    "traffic_side（走行側）――日本は左側通行なので、道路の左側に車が走っているかを確認。",  
    "road_marking（路面標示）――白線・黄線の有無・色・形は国や地域で特徴的です。",  
    "sign（標識）――形や色、背景の赤・青・緑の組み合わせは日本と他国で大きく異なります。特に三角形の警告標識は赤枠が基本です。"
  ],  
  "summary": "現在の観察で日本語サインが決め手となり正解できましたが、言語情報が欠けた場合でも判定できるよう、交通側・路面標示・標識の観察を強化してください。これらは多くの地域で明確に異なる手がかりとなります。"
  ,"vocabulary": [  
    { "canonicalTerm":"bollard", "learnerWrote":"ガードレールが黄色い", "note":"日本では道路分離用のボラードは白や銀色が多く、黄色は工事区間や特定の地域で見られることがあります。" }  
  ]  

  ,"wrongReasoning": []  
}

{
  "discoveries": [
    "「カーブミラーに日本語で注意」と記載されていた点は、正解タグの **script（かな・漢字）** と一致しています。辞書上ではこの文字種は **JP のみ 1 件** と示されているため、国を絞り込む決定的手がかりとなります。"
  ],
  "discriminationHint": "黄色のボラードは目に入りましたが、辞書では **IS（黄）** や **DK（黄）** など複数国に該当し、単独では日本を特定できません。したがって「決め手」に含める必要はありません。",
  "failureModeExplanation": "見落としはありません。『視認できないスロット』として挙げられた traffic_side は、実際には画像では確認できなかったため、あなたの見落しではなく「見えない」扱いです。",
  "judgmentUnavailable": false,
  "missedClues": [],
  "nextPriority": [
    "road_marking",
    "sign",
    "pole"
  ],
  "summary": "日本語表記のサインが唯一、辞書上で Japan に限定される手がかりだったので、正しく「script」だけを根拠に候補国を決めた点は的確です。次回は、道路標示（白線・黄線）や標識の形・色、電柱・街灯のデザインなど、辞書に国別情報があるスロットをまず確認すると、さらに確実に絞り込めます。"
  ,"vocabulary": [
    {
      "canonicalTerm": "カザフ語固有のキリル字（Қ Ғ Ә Ң Ө Ұ Ү Һ І）",
      "learnerWrote": "日本語で注意と記載",
      "note": "辞書上の正式名称は「ref_script_japanese_kana_kanji」"
    }
  ]

  ,"wrongReasoning": [
    {
      "explanation": "黄色ボラードは日本限定ではないので、単独で国を決める根拠にはできません。"
    	,
      "slot": "bollard"
    }
  ]
}
